&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Scorpion pi&#233;geur d&#233;moniaque&lt;div style=&quot;float:right;&quot;&gt;FP 9&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Cr&#233;ature magique&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Cr&#233;ature magique.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Ruines-donjons&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Ruines-donjons.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Temp&#233;r&#233;&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Temp&#233;r&#233;.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Guide de la Plaie du monde p.62&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 6 400
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Cr&#233;ature-Magique.html&quot; title=&quot;Cr&#233;ature magique&quot;&gt;Cr&#233;ature magique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Type-Vermine.html&quot; title=&quot;Vermine&quot;&gt;vermine&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Alt&#233;r&#233;.html&quot; title=&quot;Alt&#233;r&#233; (sous-type)&quot;&gt;alt&#233;r&#233;e&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-D&#233;mon.html&quot; title=&quot;D&#233;mon (sous-type)&quot;&gt;d&#233;mon&lt;/a&gt;) de taille TG, CM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +2 ; &lt;b&gt;Sens&lt;/b&gt; vision dans le noir &#224; 18 m, perception des vibrations &#224;
18 m ; Perception +19
&lt;/div&gt;
&lt;div class=&quot;box&quot;&gt;D&#201;FENSES&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 24, contact 11, pris au d&#233;pourvu 21 (Dex +2, esquive +1, naturelle +13, taille -2)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 115 (10d8+70)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +7, &lt;b&gt;Vig&lt;/b&gt; +13, &lt;b&gt;Vol&lt;/b&gt; +7
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;RD&lt;/b&gt; 5/fer froid ; &lt;b&gt;Immunit&#233;&lt;/b&gt; &#233;lectricit&#233;, poison ; &lt;b&gt;R&#233;sistance&lt;/b&gt; acide 10,
froid 10, feu 10
&lt;/div&gt;
&lt;div class=&quot;box&quot;&gt;ATTAQUE&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 15 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; 2 pinces, +15 (1d8+10 plus &#233;treinte) et dard, +15 (1d8+10 plus poison) ,(consid&#233;r&#233;es comme Chaotique mauvaise)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Espace occup&#233;&lt;/b&gt; 4,50 m ; &lt;b&gt;Allonge&lt;/b&gt; 4,50 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; attaque soudaine, constriction (1d8+10), dernier sursaut (DD 21, 9d6 d&#233;g&#226;ts de froid)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pouvoirs magiques&lt;/b&gt; (NLS 9 ; concentration +11)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
&lt;i&gt;1/jour&lt;/i&gt; — fl&#233;au d’insectes, t&#233;n&#232;bres, vomir une nu&#233;e
&lt;/div&gt;
&lt;div class=&quot;box&quot;&gt;STATISTIQUES&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 31, &lt;b&gt;Dex&lt;/b&gt; 15, &lt;b&gt;Con&lt;/b&gt; 22, &lt;b&gt;Int&lt;/b&gt; 10, &lt;b&gt;Sag&lt;/b&gt; 14, &lt;b&gt;Cha&lt;/b&gt; 15
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +7 ; &lt;b&gt;BMO&lt;/b&gt; +19 (+23 pour la lutte) ; &lt;b&gt;DMD&lt;/b&gt; 32 (44 contre le croc-en-jambe)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; Attaque en puissance, Esquive, Frappe d&#233;cisive, R&#233;flexes surhumains,
Robustesse, Talent (Discr&#233;tion)S, Volont&#233; de fer
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; Acrobaties +15, Discr&#233;tion +21 (+29 en for&#234;t), Escalade +23, Perception +19
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Modificateurs raciaux&lt;/b&gt; +4 en Perception, +8 en Discr&#233;tion (+16 en for&#234;t)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; abyssal, c&#233;leste, draconique ; t&#233;l&#233;pathie &#224; 30 m
&lt;/div&gt;
&lt;div class=&quot;box&quot;&gt;&#201;COLOGIE&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Environnement&lt;/b&gt; tous
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Organisation&lt;/b&gt; solitaire, couple ou colonie (3-10)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Tr&#233;sor&lt;/b&gt; standard
&lt;/div&gt;
&lt;div class=&quot;box&quot;&gt;POUVOIRS SP&#201;CIAUX&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaque soudaine (Ext).&lt;/b&gt; Lors d’un round de surprise, le scorpion pi&#233;geur
d&#233;moniaque peut agir comme s’il disposait d’un round complet
plut&#244;t qu’une seule action simple.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Poison (Ext).&lt;/b&gt; Dard — blessure ; JdS Vigueur DD 21 ; fr&#233;quence 1/
round pendant 6 rounds ; effet affaiblissement temporaire de 1d4
For ; gu&#233;rison 2 r&#233;ussites cons&#233;cutives.
&lt;/div&gt;
&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div class=&quot;BD&quot;&gt;
Voir l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Vermine-D&#233;moniaque,-Arch&#233;type.html&quot; title=&quot;Vermine d&#233;moniaque, arch&#233;type&quot;&gt;arch&#233;type&lt;/a&gt;&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Cette vermine d&#233;mesur&#233;e pr&#233;sente des caract&#233;ristiques d&#233;moniaques et
un reflet &#233;vident d’intelligence au fond des yeux.&lt;/i&gt;
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
